// 9 PM scoreboard against the sprint plan (25 Oct – 15 Nov 2026). Targets from the sprint document.
const rows = $input.all().map(i => i.json).filter(r => r['Lead ID']);
const ist = t => new Date(new Date(t).getTime() + 330 * 60000).toISOString().slice(0, 10);
const today = ist(Date.now());
const reached = { walked_in: 1, proposal: 2, signed: 3, client: 3, past_client: 3 };
const count = f => rows.filter(f).length;
const sprint = rows.filter(r => r['First enquiry'] && ist(r['First enquiry']) >= '2026-10-25');
const m = {
  leads: sprint.length,
  leadsToday: count(r => r['First enquiry'] && ist(r['First enquiry']) === today),
  qualified: sprint.filter(r => r['Qualified'] === 'YES').length,
  booked: sprint.filter(r => ['visit_booked', 'no_show', 'walked_in', 'proposal', 'signed', 'client'].includes(r['Stage'])).length,
  walkins: sprint.filter(r => reached[r['Stage']] >= 1).length,
  proposals: sprint.filter(r => reached[r['Stage']] >= 2).length,
  signed: sprint.filter(r => reached[r['Stage']] >= 3).length,
  waiting: count(r => r['Paused until'] && Date.parse(r['Paused until']) > Date.now()),
  optedOut: count(r => r['Stage'] === 'opted_out'),
  signedValue: sprint.reduce((s, r) => s + (Number(r['Signed value (₹)']) || 0), 0),
};
const T = today <= '2026-11-05' ? { label: 'by 5 Nov', leads: 140, qualified: 50, booked: 15, walkins: 9, proposals: 7, signed: 0 }
                                : { label: 'by 15 Nov', leads: 258, qualified: 92, booked: 26, walkins: 15, proposals: 12, signed: 2 };
const line = (k, n) => `${k.padEnd(14)} ${String(m[n]).padStart(4)}  / ${T[n]} ${T.label}${m[n] < T[n] ? '' : '  ✓'}`;
const text = [
  `Edgehomes · 9 PM scoreboard · ${today}`, '',
  line('Leads', 'leads'), line('Qualified', 'qualified'), line('Visits booked', 'booked'), line('Walk-ins', 'walkins'),
  line('Proposals', 'proposals'), line('Signed', 'signed'), '',
  `New leads today: ${m.leadsToday}`, `Waiting for a person now: ${m.waiting}`, `Opted out (all time): ${m.optedOut}`,
  `Signed value: ₹${m.signedValue.toLocaleString('en-IN')}`, '',
  'Red flags: < 10 leads a day for 2 days · qualified < 25% · < 4 walk-ins on 3 Nov · 0 signed by 12 Nov.',
  'Add today\'s ad spend in the sheet to get cost per qualified lead (target ≤ ₹1,400).',
].join('\n');
return [{ json: { text, ...m } }];
